const invoice = $("Crear Cabecera Factura").first().json;
const total = $("Guardia de Presupuesto").first().json.total_factura;

return [{
  json: {
    success: true,
    output: `✅ Factura #${invoice.doc_no} creada exitosamente por un total de ${total}.`,
    invoice_id: invoice.id,
    amount: total
  }
}];

let parsedQuery = {};
try {
  parsedQuery = JSON.parse($input.first().json.query);
} catch (error) {
  throw new Error("El campo 'query' no contiene un JSON válido.");
}

const items = parsedQuery.items || [];
if (items.length === 0) {
  throw new Error("No se enviaron items para facturar en el campo query.");
}

const totalFactura = items.reduce((sum, item) => sum + parseFloat(item.amount), 0);

return [{
  json: {
    ...parsedQuery,
    order_id: $input.first().json.order_id,
    total_factura: totalFactura,
    timestamp: new Date().toISOString()
  }
}];

const saldos = $input.all().map(r => r.json);
const inputOriginal = $("Validar y Calcular Total").first().json;

// Enriquecemos cada item con la traza del descuento del presupuesto.
// Solo se copia cuando se factura la LINEA COMPLETA por primera vez
// (amount == total neto de la quote_item y nada facturado aun): prorratear
// un descuento en una factura parcial no tiene una lectura clara, asi que
// esas lineas van a precio plano (gross_total = amount, sin descuento).
const items = inputOriginal.items.map((item) => {
  const saldoInfo = saldos.find(s => s.quote_item_id === item.quote_item_id);
  if (saldoInfo && item.amount > (saldoInfo.saldo_disponible + 0.01)) {
    throw new Error(`Exceso de monto: Item ${item.quote_item_id} pide ${item.amount} pero solo quedan ${saldoInfo.saldo_disponible}`);
  }

  const netoLinea = saldoInfo ? Number(saldoInfo.total_presupuesto) : null;
  const grossLinea = saldoInfo && saldoInfo.gross_total != null ? Number(saldoInfo.gross_total) : null;
  const lineaCompleta = saldoInfo != null && netoLinea != null
    && Math.abs(Number(item.amount) - netoLinea) < 0.01
    && Number(saldoInfo.ya_facturado || 0) < 0.01;

  if (lineaCompleta && saldoInfo.discount_mode) {
    return {
      ...item,
      gross_total: grossLinea != null ? grossLinea : Number(item.amount),
      discount_mode: saldoInfo.discount_mode,
      discount_value: saldoInfo.discount_value != null ? Number(saldoInfo.discount_value) : null,
      discount_amount: saldoInfo.discount_amount != null ? Number(saldoInfo.discount_amount) : null,
    };
  }

  return {
    ...item,
    gross_total: Number(item.amount),
    discount_mode: null,
    discount_value: null,
    discount_amount: null,
  };
});

const round2 = (n) => Math.round((n + Number.EPSILON) * 100) / 100;
const gross_factura = round2(items.reduce((s, it) => s + Number(it.gross_total != null ? it.gross_total : it.amount), 0));
const descuento_factura = round2(items.reduce((s, it) => s + Number(it.discount_amount || 0), 0));

return [{ json: { ...inputOriginal, items, gross_factura, descuento_factura } }];

