const invoiceId = $("Crear Cabecera Factura").first().json.id;
const items = $("Guardia de Presupuesto").first().json.items;

const values = items
  .map((item) => {
    let stepsValue = "";

    if (Array.isArray(item.step_names)) {
      stepsValue = item.step_names.join(", ");
    } else if (typeof item.step_names === "string") {
      stepsValue = item.step_names;
    } else {
      stepsValue = "";
    }

    const safeSteps = stepsValue.replace(/'/g, "''");

    // `total` viaja NETO; `unit_price` = bruto unitario (quantity = 1) para
    // que unit_price * quantity == gross_total, como en el resto de flujos.
    const netTotal = Number(item.amount);
    const grossTotal = item.gross_total != null ? Number(item.gross_total) : netTotal;
    const discMode = item.discount_mode ? `'${String(item.discount_mode).replace(/'/g, "''")}'` : "NULL";
    const discValue = item.discount_value != null ? Number(item.discount_value) : "NULL";
    const discAmount = item.discount_amount != null ? Number(item.discount_amount) : "NULL";

    return `(
    ${invoiceId}, 
    (SELECT id FROM order_items WHERE quote_item_id = ${item.quote_item_id} LIMIT 1), 
    1, 
    ${grossTotal}, 
    ${netTotal}, 
    ${item.service_id}, 
    ${safeSteps ? `'${safeSteps}'` : "NULL"}, 
    ${grossTotal}, 
    ${discMode}, 
    ${discValue}, 
    ${discAmount}
  )`;
  })
  .join(",");

return [
  {
    query: `INSERT INTO invoice_items (invoice_id, order_item_id, quantity, unit_price, total, service_id, steps, gross_total, discount_mode, discount_value, discount_amount) VALUES ${values}`,
  },
];
